using System;using System.Collections.Generic;using Game.Components;using Unity.Entities;using Unity.Mathematics;namespace Game.Runtime{internal sealed partial class GeneratedRuntimeSpawnProcessor{
 float _nextRuntimeSpawnRequestProbeAt;readonly List<int> _pendingSpawnRequestIndices=new List<int>();bool _forcePublishNextUpdate;readonly GeneratedRoadMask _skirmishRoads;readonly GeneratedBuildingMask _skirmishBuildings;
 internal GeneratedRuntimeSpawnProcessor(GeneratedRoadMask roads,GeneratedBuildingMask buildings){_skirmishRoads=roads??throw new ArgumentNullException(nameof(roads));_skirmishBuildings=buildings??throw new ArgumentNullException(nameof(buildings));}
 internal bool PublishRequired=>_forcePublishNextUpdate;
 internal void Process(GeneratedConfiguredDefinitionSource definitions,BuildingRuntimeSpawnCompositionSystemHelper spawn,BuildingRuntimeSpawnCompositionSystemHelper.Context context,EntityManager em,Entity boundary,float now,bool forceScan=false){if(float.IsNaN(now)||float.IsInfinity(now))throw new NotSupportedException("Finite original simulation time required");var rows=EnsureBoundaryBuffer<BuildingRuntimeSpawnRequest>(em,boundary);for(int i=0;i<rows.Length;i++){var r=rows[i];if(r.Status!=BuildingRuntimeSpawnRequest.Pending)continue;bool paid=SkirmishEnemyConstructionAdapter.IsConstructionRequest(r);bool legacy=IsLegacyInitialRequest(em,r);bool planner=IsOriginalAiPlannerRequest(em,r);if((!paid&&!legacy&&!planner&&(r.RequestKind!=BuildingRuntimeSpawnRequest.KindBuilding||r.AuthoredStartingGrant==0||r.RequirePreferredOrigin!=0))||(paid&&(r.AuthoredStartingGrant!=0||r.RequirePreferredOrigin!=1))||r.AllowNonBuildableEnemy!=0||r.RotateVertical!=0)throw new NotSupportedException("Original starting grant, AI-plan-owned request, or exact source enemy-paid construction request required");if(em.Exists(r.PlanEntity)&&em.HasComponent<CampaignMissionRuntimeComponent>(r.PlanEntity))throw new NotSupportedException("Active Campaign branch unsupported");if(TryResolveConfiguredBuildingDefinition(definitions,r.BuildingId.ToString(),out var d)&&(!d.SourceMetadataComplete||d.HasRunway||d.IsWall||BuildingBarrierUtilitySystemHelper.IsWallGateDefinition(d)))throw new NotSupportedException("Active wall/runway or incomplete metadata unsupported");}ProcessRuntimeSpawnRequests(definitions,spawn,context,em,boundary,now,forceScan);}
 internal static bool IsOriginalAiPlannerRequest(EntityManager em,BuildingRuntimeSpawnRequest r){if(r.RequestKind!=BuildingRuntimeSpawnRequest.KindBuilding||r.AuthoredStartingGrant!=0||r.RequirePreferredOrigin!=0||r.HasOwnerFaction!=1||r.PlanEntity==Entity.Null||!em.Exists(r.PlanEntity)||!em.HasComponent<Game.Components.AIBuildPlan>(r.PlanEntity)||!em.HasBuffer<Game.Components.AIBuildPlanEntry>(r.PlanEntity)||em.HasComponent<CampaignMissionRuntimeComponent>(r.PlanEntity))return false;var plan=em.GetComponentData<Game.Components.AIBuildPlan>(r.PlanEntity);if(plan.FactionId!=r.FactionId||r.EntryIndex<0)return false;var entries=em.GetBuffer<Game.Components.AIBuildPlanEntry>(r.PlanEntity);if(r.EntryIndex>=entries.Length)return false;return BuildingDefinitionPrefabSystemHelper.NormalizeSpawnableKey(entries[r.EntryIndex].BuildingId.ToString())==r.BuildingId.ToString();}
 internal static bool IsLegacyInitialRequest(EntityManager em, BuildingRuntimeSpawnRequest r){if(r.RequestKind!=BuildingRuntimeSpawnRequest.KindBuilding||r.AuthoredStartingGrant!=0||r.RequirePreferredOrigin!=1||r.HasOwnerFaction==0||r.PlanEntity==Entity.Null||!em.Exists(r.PlanEntity)||!em.HasComponent<InitialUnitsSpawnConfig>(r.PlanEntity)||em.HasComponent<SkirmishExpandedSessionComponent>(r.PlanEntity)||!em.HasBuffer<InitialUnitsFactionBuildingSpawnEntry>(r.PlanEntity)||!em.HasBuffer<InitialUnitsFactionSpawnEntry>(r.PlanEntity))return false;using var skirmish=em.CreateEntityQuery(typeof(SkirmishMatchState));if(skirmish.IsEmptyIgnoreFilter)return false;var buildings=em.GetBuffer<InitialUnitsFactionBuildingSpawnEntry>(r.PlanEntity);var spawns=em.GetBuffer<InitialUnitsFactionSpawnEntry>(r.PlanEntity);foreach(var b in buildings)foreach(var f in spawns)if(b.FactionId==r.FactionId&&f.FactionId==r.FactionId&&BuildingDefinitionPrefabSystemHelper.NormalizeSpawnableKey(b.PrefabLookupKey.ToString())==r.BuildingId.ToString()&&math.all(f.SpawnCell+b.OriginOffset==r.PreferredOrigin))return true;return false;}
 static DynamicBuffer<T> EnsureBoundaryBuffer<T>(EntityManager entityManager,Entity boundary)where T:struct,IBufferElementData{if(!entityManager.HasBuffer<T>(boundary))entityManager.AddBuffer<T>(boundary);return entityManager.GetBuffer<T>(boundary);}
 static bool IsRegisteredMissionRoadObstruction(EntityManager em,in BuildingRuntimeSpawnRequest request,RuntimeDefinition definition,BuildingRuntimeSpawnCompositionSystemHelper.Context context)=>throw new NotSupportedException("Active mission obstruction unsupported");
 }

 internal sealed class GeneratedRoadMask{readonly GridConfig admitted;readonly bool[] roads,water,sidewalks;internal GeneratedRoadMask(GridConfig grid,bool[] roads,bool[] water,bool[] sidewalks,bool inactiveWaterDiagnostic=false){admitted=grid;int n=checked(grid.Width*grid.Height);if(inactiveWaterDiagnostic?water!=null:water==null||water.Length!=n)throw new NotSupportedException("Exact water scope required");foreach(var x in new[]{roads,sidewalks})if(x==null||x.Length!=n)throw new NotSupportedException("All source geometry masks required");this.roads=(bool[])roads.Clone();this.water=water==null?null:(bool[])water.Clone();this.sidewalks=(bool[])sidewalks.Clone();}internal void Ensure(EntityManager em,EntityQuery q,GridConfig g){Validate(g);}void Validate(GridConfig g){if(g.Width!=admitted.Width||g.Height!=admitted.Height||g.CellSize!=admitted.CellSize||g.Origin.x!=admitted.Origin.x||g.Origin.z!=admitted.Origin.z)throw new NotSupportedException("Mask/grid identity mismatch");}bool Overlap(bool[] mask,GridConfig g,Vector2Int at,Vector2Int size){Validate(g);for(int y=at.y;y<at.y+size.y;y++)for(int x=at.x;x<at.x+size.x;x++)if(x>=0&&y>=0&&x<g.Width&&y<g.Height&&mask[y*g.Width+x])return true;return false;}internal bool Overlaps(GridConfig g,Vector2Int at,Vector2Int size)=>Overlap(roads,g,at,size);internal bool OverlapsWater(GridConfig g,Vector2Int at,Vector2Int size)=>water!=null&&Overlap(water,g,at,size);internal bool[] GetSidewalks()=>sidewalks;}
 internal sealed class GeneratedBuildingMask{readonly GridConfig admitted;readonly bool[] cells;internal GeneratedBuildingMask(GridConfig g,bool[] cells){if(cells==null||cells.Length!=checked(g.Width*g.Height))throw new NotSupportedException("Authored building mask required");admitted=g;this.cells=(bool[])cells.Clone();}internal bool IsReady=>true;internal void Ensure(EntityManager em,GridConfig g){if(g.Width!=admitted.Width||g.Height!=admitted.Height||g.CellSize!=admitted.CellSize||g.Origin.x!=admitted.Origin.x||g.Origin.z!=admitted.Origin.z)throw new NotSupportedException("Mask/grid identity mismatch");}internal bool Overlaps(GridConfig g,Vector2Int at,Vector2Int size){Ensure(null,g);for(int y=at.y;y<at.y+size.y;y++)for(int x=at.x;x<at.x+size.x;x++)if(x>=0&&y>=0&&x<g.Width&&y<g.Height&&cells[y*g.Width+x])return true;return false;}}
 internal static class GeneratedCheckpointComponentObject{internal static void AddComponentObject(this EntityManager em,Entity e,SkirmishNativeBuildingCheckpointRecord value)=>em.AddComponentData(e,value);}
